Soft delete: sets active=false (database 0) and retains the season ID and history. Each Send uses a fresh key so delete still works after a restore. 201 is the current mutation handler success status.

Original folder: 06 — Master management: list, update and safe delete

prerequest script:
```javascript
// Leave season_retry_key empty for a new operation; reuse the previous key only to retry the identical request.
const key = pm.variables.get('season_retry_key') || 'season-delete-' + pm.variables.replaceIn('{{$guid}}');
pm.variables.set('season_request_key', key);
console.log('Season Idempotency-Key:', key);
if (pm.request.body && pm.request.body.mode === 'raw') {
 const resolved = pm.variables.replaceIn(pm.request.body.raw);
 function stop(message) { pm.execution.skipRequest(); throw new Error(message); }
 const missing = [...resolved.matchAll(/{{([^}]+)}}/g)].map(m => m[1]);
 if (missing.length) stop('Set Postman variables: ' + [...new Set(missing)].join(', '));
 let body; try { body = JSON.parse(resolved); } catch (error) { stop('Invalid JSON: ' + error.message); }
 function convert(value) {
  if (Array.isArray(value)) return value.map(convert);
  if (value && typeof value === 'object') for (const key of Object.keys(value)) {
   if (key === 'id' || key.endsWith('_id')) {
    if (value[key] === null) continue;
    const n = Number(value[key]);
    if (!Number.isSafeInteger(n) || n <= 0) stop(key + ' must be a positive numeric ID. Run location setup or create/list the required record first.');
    value[key] = n;
   } else value[key] = convert(value[key]);
  }
  return value;
 }
 pm.request.body.update(JSON.stringify(convert(body), null, 2));
}
```

test script:
```javascript
pm.test('HTTP success', () => pm.expect(pm.response.code).to.be.oneOf([200,201]));
const response = pm.response.json();
pm.test('Season status saved', () => { pm.expect(response.ok).to.eql(true); pm.expect(response.data.active).to.eql(false); });
pm.test('New operation is not replayed', () => { if (!pm.variables.get('season_retry_key')) pm.expect(response.replayed).to.eql(false); });
```

